import{_ as a,o as n,a as p,b as t}from"./app.DKoEZOcr.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"数学函数","link":"/api/SIMT-API/math_functions/math_functions"},{"text":"fp8类型","link":"/api/SIMT-API/math_functions/fp8_type/fp8_type"},{"text":"fp8数据转换函数","link":"/api/SIMT-API/math_functions/fp8_type/fp8_conversion_functions/fp8_conversion_functions"},{"text":"__asc_cvt_float_to_fp8","link":"/api/SIMT-API/math_functions/fp8_type/fp8_conversion_functions/__asc_cvt_float_to_fp8"}]},"headers":[],"relativePath":"api/SIMT-API/math_functions/fp8_type/fp8_conversion_functions/__asc_cvt_float_to_fp8.md","filePath":"api/SIMT-API/math_functions/fp8_type/fp8_conversion_functions/__asc_cvt_float_to_fp8.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787736726000}'),l={name:"api/SIMT-API/math_functions/fp8_type/fp8_conversion_functions/__asc_cvt_float_to_fp8.md"};function c(_,s,e,d,i,o){return n(),p("div",null,[...s[0]||(s[0]=[t(`<div><article class="markdown-body"><h1>__asc_cvt_float_to_fp8</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>将float类型数据按照CAST_RINT模式转换为指定类型（<code>float8_e4m3_t</code>和<code>float8_e5m2_t</code>）的8位浮点数，并根据指定的饱和模式（饱和或非饱和）进行溢出处理。转换结果以位级形式存储为<code>__asc_fp8_storage_t</code>类型，该类型为unsigned char，用于存储<code>float8_e4m3_t</code>或<code>float8_e5m2_t</code>类型的数据。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kr">inline</span><span class="w"> </span><span class="n">__asc_fp8_storage_t</span><span class="w"> </span><span class="n">__asc_cvt_float_to_fp8</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">__asc_saturation_t</span><span class="w"> </span><span class="n">saturation</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">__asc_fp8_interpretation_t</span><span class="w"> </span><span class="n">fp8_interpretation</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>x</td><td>输入</td><td>源操作数。</td></tr><tr><td>saturation</td><td>输入</td><td>控制饱和行为，支持的取值为：__ASC_NOSAT、__ASC_SATFINITE。<br><br>__ASC_NOSAT表示使用非饱和模式，__ASC_SATFINITE表示使用饱和模式。</td></tr><tr><td>fp8_interpretation</td><td>输入</td><td>指定转换类型，支持的取值为：__ASC_E4M3、__ASC_E5M2。<br><br>__ASC_E4M3表示转换为<code>float8_e4m3_t</code>格式的浮点数，__ASC_E5M2表示转换为<code>float8_e5m2_t</code>格式的浮点数。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>输入遵循CAST_RINT模式，根据指定的8位浮点数类型和指定的饱和模式，转换成的<code>__asc_fp8_storage_t</code>类型数据。本接口受全局饱和模式影响，特殊值如下：</p><ul><li><p>fp8_interpretation参数为__ASC_E4M3时：</p><table><thead><tr><th>输入</th><th>非饱和模式返回值</th><th>饱和模式返回值</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td></tr><tr><td>nan</td><td>nan</td><td>+0</td></tr><tr><td>±inf</td><td>nan</td><td>±448</td></tr><tr><td>超出float8_e4m3_t范围的正值</td><td>nan</td><td>448</td></tr><tr><td>超出float8_e4m3_t范围的负值</td><td>nan</td><td>-448</td></tr></tbody></table></li><li><p>fp8_interpretation的参数为__ASC_E5M2时：</p><table><thead><tr><th>输入</th><th>非饱和模式返回值</th><th>饱和模式返回值</th></tr></thead><tbody><tr><td>±0</td><td>±0</td><td>±0</td></tr><tr><td>nan</td><td>nan</td><td>+0</td></tr><tr><td>±inf</td><td>±inf</td><td>±57344</td></tr><tr><td>超出float8_e5m2_t范围的正值</td><td>inf</td><td>57344</td></tr><tr><td>超出float8_e5m2_t范围的负值</td><td>-inf</td><td>-57344</td></tr></tbody></table></li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>使用此接口前需将CTRL[60]寄存器设置为0，否则饱和模式不生效。设置方式请参见<a href="../../data_type_conversion/overview.html#section1194916101549">控制饱和行为的方式</a>。</p><p>SIMT编程场景当前不支持使用该接口。</p><h2 id="需要包含的头文件">需要包含的头文件<a class="header-anchor" href="#需要包含的头文件">​</a></h2><p>使用该接口需要包含<code>simt_api/asc_fp8.h</code>头文件。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;simt_api/asc_fp8.h&quot;</span>
</code></pre></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>SIMD与SIMT混合编程场景：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simt_vf__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="mi">1024</span><span class="p">)</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">simt_asc_cvt_float_to_fp8</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">idx</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">output</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">__asc_cvt_float_to_fp8</span><span class="p">(</span><span class="n">input</span><span class="p">[</span><span class="n">idx</span><span class="p">],</span><span class="w"> </span><span class="n">__ASC_NOSAT</span><span class="p">,</span><span class="w"> </span><span class="n">__ASC_E4M3</span><span class="p">);</span>
<span class="p">}</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">cast_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simt_asc_cvt_float_to_fp8</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dim3</span><span class="p">(</span><span class="mi">1024</span><span class="p">),</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></li></ul></article></div>`,1)])])}const f=a(l,[["render",c]]);export{r as __pageData,f as default};
